// Convierte lo que entrega el Error Trigger en un mensaje corto para Discord.
// Dos formas segun de donde venga el fallo:
//   $json.trigger   -> murio el trigger del workflow (p.ej. la conexion IMAP)
//   $json.execution -> fallo un nodo durante una ejecucion
//
// Sin literales multilinea a proposito: el unico salto de linea es el join de
// abajo. Este nodo estuvo 14 ejecuciones seguidas sin compilar porque un '\n'
// quedo guardado como salto de linea REAL dentro de comillas simples, y nadie
// se entero porque lo roto era justamente el aviso de errores.
// compilan.test.mjs existe por esto.
const wf = $json.workflow || {};
const lineas = [`🔴 **n8n: error en "${wf.name || '?'}"**`];

if ($json.trigger) {
  const t = $json.trigger;
  lineas.push(`Trigger: ${t.error?.node?.name || '?'}`);
  lineas.push(t.error?.message || t.error?.name || 'error sin mensaje');
} else {
  const e = $json.execution || {};
  lineas.push(`Nodo: ${e.lastNodeExecuted || '?'}`);
  lineas.push(e.error?.message || 'error sin mensaje');
  if (e.url) lineas.push(e.url);
}

return [{ json: { content: lineas.join('\n') } }];
